// audio.c - the voices and the jukebox, both on the SPU (the PS1 sound chip).
// The jukebox plays SEQUENCES: every song is its note events plus small instrument samples (tools/build_music.py runs the GBA game's
// own XM converter, so the notes, volumes and pans are the GBA version's). One song's samples sit in sound memory; a 480 Hz timer
// interrupt walks the rows and keys the notes on, so the chip does all the playing and the timing never depends on the frame rate.
#include "audio.h"
#include <psxspu.h>
#include <psxcd.h>
#include <hwregs_c.h>
#include "songs.inc"     // GENERATED by tools/build_music.py: the song table (seconds, name, artist)

extern const u8 voices_bin[];
extern const u32 voices_bin_size;

#define MUS_CH     16                  // music voices 0..15 (every song uses at most 16 channels)
#define CLIP_CH0   16                  // voice clips on 16..23
#define CLIP_N     8
#define MIXR       18157               // the rate the GBA converter's timing is counted in
#define TICK_HZ    480                 // the sequencer's timer
#define SEQ_MAX    (100 * 1024)        // the biggest song's sequence block (worthless_clouds: 94 KB)

// ---- sound memory ----
#define ALLOC_START 0x1010
static int spu_next = ALLOC_START, song_base;
static int voice_addr[VOICE_N], voice_rate[VOICE_N];
static int next_clip = 0;
static int spu_ok;

static void spu_write(int addr, const void *data, int size) {
    SpuSetTransferMode(SPU_TRANSFER_BY_DMA);
    SpuSetTransferStartAddr(addr);
    SpuWrite((const u32 *)data, (size + 63) & ~63);
    SpuIsTransferCompleted(SPU_TRANSFER_WAIT);
}
static int upload_sample(const void *data, int size) {
    int addr = spu_next;
    spu_write(addr, data, size);
    spu_next = addr + ((size + 63) & ~63);
    return addr;
}

void audio_voice(int v) {
    if (!spu_ok || v < 0 || v >= VOICE_N || !voice_addr[v]) return;
    int ch = CLIP_CH0 + next_clip;
    SpuSetKey(0, 1 << ch);
    SPU_CH_FREQ(ch) = getSPUSampleRate(voice_rate[v]);
    SPU_CH_ADDR(ch) = getSPUAddr(voice_addr[v]);
    SPU_CH_VOL_L(ch) = 0x2fff;
    SPU_CH_VOL_R(ch) = 0x2fff;
    SPU_CH_ADSR1(ch) = 0x00ff;
    SPU_CH_ADSR2(ch) = 0x0000;
    SpuSetKey(1, 1 << ch);
    next_clip = (next_clip + 1) % CLIP_N;
}

// ---- the song file (SONGS.BIN): a one-sector index, then per song its sequence sectors and its sample sectors ----
static u32 seqbuf[SEQ_MAX / 4];
static CdlLOC songs_loc;
static int cd_ok;
static struct { u32 sector, seq_sectors, smp_sectors, smp_bytes; } sidx[NSONGS];

// ---- the sequencer (all of this is read inside the timer interrupt) ----
typedef struct {
    u32 magic, nord, loop, rowN, rfr, npat, ninst, nvt, ev_size, smp_size, seconds;
    u32 o_order, o_rows, o_patoff, o_vt, o_pitch, o_smpoff, o_bus, o_ev, pad;
} SeqHeader;
static volatile int sq_on;
static const SeqHeader *sq;
static const u8 *sq_order, *sq_bus, *sq_ev;
static const u16 *sq_rows, *sq_vt, *sq_pitch;
static const u32 *sq_patoff, *sq_smpoff;
static int sq_ord, sq_row;
static u32 sq_acc, sq_rowlen;          // the row clock: +MIXR*256 per tick; a row is (rowN*256 + rfr) * TICK_HZ
static volatile int sq_laps;
static int music_vol = 320;            // 256 = the GBA level (a touch louder: the SPU has the headroom)

static void seq_row(void) {
    const u8 *e = sq_ev + sq_patoff[sq_order[sq_ord]];
    int r = sq_row, n;
    for (;;) {                                           // find this row in the pattern's event stream
        int h = *e++;
        if (h & 0x80) { h &= 0x7f; if (r < h) { n = 0; break; } r -= h; }
        else if (r-- == 0) { n = h; break; }
        else e += 3 * h;
    }
    u32 on = 0;
    while (n--) {
        u32 w = e[0] | ((u32)e[1] << 8) | ((u32)e[2] << 16); e += 3;
        u32 t = sq_vt[(w & 255) | ((w >> 22) << 8)];
        int ch = t & 15, in = (t >> 4) & 31, bus = (t >> 9) & 7, nt = (w >> 8) & 127, vol = (w >> 15) & 127;
        if (bus > 6) bus = 3;
        u32 so = sq_smpoff[in];
        if (so == 0xffffffff || nt >= 96) continue;
        int vl = (vol * sq_bus[bus] * music_vol) >> 9, vr = (vol * sq_bus[7 + bus] * music_vol) >> 9;   // the GBA's level: vol x bus / 2
        SPU_CH_VOL_L(ch) = vl > 0x3fff ? 0x3fff : vl;
        SPU_CH_VOL_R(ch) = vr > 0x3fff ? 0x3fff : vr;
        SPU_CH_FREQ(ch) = sq_pitch[in * 96 + nt];
        SPU_CH_ADDR(ch) = getSPUAddr(song_base + (int)so);
        SPU_CH_ADSR1(ch) = 0x00ff;                       // instant attack, full sustain: the sample plays as it is (one-shot)
        SPU_CH_ADSR2(ch) = 0x0005;                       // a short release, for when a note is cut
        on |= 1u << ch;
    }
    if (on) SPU_KEY_ON1 = (u16)on;
    if (++sq_row >= sq_rows[sq_order[sq_ord]]) {
        sq_row = 0;
        if (++sq_ord >= (int)sq->nord) { sq_ord = (int)sq->loop; sq_laps++; }
    }
}
static void seq_tick(void) {
    if (!sq_on) return;
    sq_acc += MIXR * 256;
    while (sq_acc >= sq_rowlen) { sq_acc -= sq_rowlen; seq_row(); }
}
static void music_silence(void) {
    sq_on = 0;
    SPU_KEY_OFF1 = 0xffff;
    for (int ch = 0; ch < MUS_CH; ch++) { SPU_CH_VOL_L(ch) = 0; SPU_CH_VOL_R(ch) = 0; }
}

// ---- REVERB: the sound chip's own, one preset per song (songs.inc fx) ----
// The delays are the hardware docs' ROOM layout (a 0x26C0-byte work area at the top of sound memory); the presets change how
// loud the reverb is, how dark (vIIR) and how long it rings (vWALL, vCOMB) - DRY, ROOM, WARM, BIG SPACE, CAVE.
#define REV_SIZE 0x26C0
#define REV_ADDR (0x80000 - REV_SIZE)
static const u16 revRoom[32] = { 0x007D, 0x005B, 0x6D80, 0x54B8, 0xBED0, 0x0000, 0x0000, 0xBA80, 0x5800, 0x5300, 0x04D6, 0x0333, 0x03F0, 0x0227,
                                 0x0374, 0x01EF, 0x0334, 0x01B5, 0x0000, 0x0000, 0x0000, 0x0000, 0x0000, 0x0000, 0x0000, 0x0000, 0x01B4, 0x0136,
                                 0x00B8, 0x005C, 0x8000, 0x8000 };
static const struct { u16 send, iir, wall, comb1, comb2; } revFx[5] = {
    { 0x0000, 0x6D80, 0xBA80, 0x54B8, 0xBED0 },   // DRY
    { 0x1600, 0x6D80, 0xBA80, 0x54B8, 0xBED0 },   // ROOM
    { 0x2000, 0x4E00, 0xB000, 0x5C00, 0xBA00 },   // WARM (darker, a little longer)
    { 0x2A00, 0x6D80, 0xA400, 0x6600, 0xB400 },   // BIG SPACE
    { 0x3000, 0x5800, 0x9C00, 0x7000, 0xAE00 },   // CAVE (long and dark)
};
static int rev_ready;
static void reverb_set(int fx) {
    if (!rev_ready) {   // the work area starts silent
        static u32 zero[256];
        for (int a = REV_ADDR; a < 0x80000; a += sizeof zero) spu_write(a, zero, sizeof zero);
        SPU_REVERB_ADDR = getSPUAddr(REV_ADDR);
        rev_ready = 1;
    }
    fx %= 5;
    for (int i = 0; i < 32; i++) {
        u16 v = revRoom[i];
        if (i == 2) v = revFx[fx].iir; if (i == 7) v = revFx[fx].wall; if (i == 3) v = revFx[fx].comb1; if (i == 4) v = revFx[fx].comb2;
        _MMIO16((IOBASE | 0x1dc0) + 2 * i) = v;
    }
    SPU_REVERB_VOL_L = revFx[fx].send; SPU_REVERB_VOL_R = revFx[fx].send;
    SPU_REVERB_ON1 = revFx[fx].send ? 0xffff : 0;     // the music voices (0..15) feed it; the voice clips stay dry
    SPU_CTRL |= 0x80;
}

// ---- jukebox ----
static int cur_song = -1, shuffle = 1;
static int play_frames;

int audio_song_count(void) { return NSONGS; }
const char *audio_song_name(int i) { return (i >= 0 && i < NSONGS) ? songs[i].name : ""; }
const char *audio_song_artist(int i) { return (i >= 0 && i < NSONGS) ? songs[i].artist : ""; }
int audio_song_len(int i) { return (i >= 0 && i < NSONGS) ? songs[i].seconds : 0; }
int audio_jukebox_current(void) { return cur_song; }
int audio_jukebox_elapsed(void) { return play_frames / 60; }
void audio_jukebox_toggle_shuffle(void) { shuffle ^= 1; }
int audio_jukebox_shuffle(void) { return shuffle; }
int audio_cd_ok(void) { return cd_ok; }

static int cd_read(u32 sector, int count, void *buf) {
    CdlLOC loc;
    CdIntToPos(CdPosToInt(&songs_loc) + (int)sector, &loc);
    if (!CdControl(CdlSetloc, &loc, 0)) return 0;
    if (!CdRead(count, (u32 *)buf, CdlModeSpeed)) return 0;
    return CdReadSync(0, 0) >= 0;
}

void audio_jukebox_stop(void) {
    music_silence();
    cur_song = -1;
}
void audio_jukebox_play(int i) {
    if (!cd_ok || i < 0 || i >= NSONGS) return;
    music_silence();
    cur_song = -1;
    if (song_base + (int)sidx[i].smp_bytes > REV_ADDR) return;     // (never into the reverb's work area)
    // the samples: through the sequence buffer, a chunk at a time, into sound memory after the voices
    int left = (int)sidx[i].smp_sectors, sec = (int)(sidx[i].sector + sidx[i].seq_sectors), addr = song_base;
    while (left > 0) {
        int n = left > SEQ_MAX / 2048 ? SEQ_MAX / 2048 : left;
        if (!cd_read((u32)sec, n, seqbuf)) return;
        spu_write(addr, seqbuf, n * 2048);
        addr += n * 2048; sec += n; left -= n;
    }
    // the sequence
    if ((int)sidx[i].seq_sectors * 2048 > SEQ_MAX || !cd_read(sidx[i].sector, (int)sidx[i].seq_sectors, seqbuf)) return;
    const u8 *b = (const u8 *)seqbuf;
    sq = (const SeqHeader *)b;
    if (sq->magic != 0x31515342) return;
    sq_order = b + sq->o_order; sq_rows = (const u16 *)(b + sq->o_rows); sq_patoff = (const u32 *)(b + sq->o_patoff);
    sq_vt = (const u16 *)(b + sq->o_vt); sq_pitch = (const u16 *)(b + sq->o_pitch); sq_smpoff = (const u32 *)(b + sq->o_smpoff);
    sq_bus = b + sq->o_bus; sq_ev = b + sq->o_ev;
    sq_ord = 0; sq_row = 0; sq_laps = 0;
    sq_rowlen = (sq->rowN * 256 + sq->rfr) * TICK_HZ;
    sq_acc = sq_rowlen - MIXR * 256;                     // the first row sounds on the first tick
    play_frames = 0; cur_song = i;
    reverb_set(songs[i].fx);
    sq_on = 1;
}
void audio_jukebox_next(void) {
    if (NSONGS == 0) return;
    int n = shuffle ? (int)(rand() % NSONGS) : (cur_song + 1) % NSONGS;
    if (shuffle && n == cur_song) n = (n + 1) % NSONGS;
    audio_jukebox_play(n);
}
void audio_update(void) {
    if (cur_song < 0) return;
    play_frames++;
    if (sq_laps > 0 && cur_song != 0) audio_jukebox_next();       // a song moves on when it has played once (THE DIPPER MAN, the title song, loops)
}

void audio_init(void) {
    SpuInit();
    spu_ok = 1;
    // the voice blob: u32 count, then {u32 offset, u32 size, u32 rate} per clip, then the ADPCM data
    const u32 *hdr = (const u32 *)voices_bin;
    int n = (int)hdr[0];
    for (int i = 0; i < VOICE_N && i < n; i++) {
        u32 off = hdr[1 + i * 3], size = hdr[2 + i * 3], rate = hdr[3 + i * 3];
        voice_addr[i] = upload_sample(voices_bin + off, (int)size);
        voice_rate[i] = (int)rate;
    }
    song_base = spu_next;                                // every song's samples go here (the biggest is SONG_SMP_MAX bytes)
    SpuSetCommonMasterVolume(0x3fff, 0x3fff);
    music_silence();
    // the disc
    cd_ok = 0;
    if (CdInit()) {
        CdlFILE f;
        if (CdSearchFile(&f, "\\SONGS.BIN;1")) {
            songs_loc = f.pos;
            if (cd_read(0, 1, seqbuf)) {
                const u32 *ix = seqbuf;
                if (ix[0] == 0x474E5342 && (int)ix[1] == NSONGS) {
                    for (int i = 0; i < NSONGS; i++) { sidx[i].sector = ix[2 + i * 4]; sidx[i].seq_sectors = ix[3 + i * 4]; sidx[i].smp_sectors = ix[4 + i * 4]; sidx[i].smp_bytes = ix[5 + i * 4]; }
                    cd_ok = 1;
                }
            }
        }
    }
    // the sequencer's clock: timer 2 (CPU clock / 8) interrupts TICK_HZ times a second
    EnterCriticalSection();
    TIMER_CTRL(2) = 0x0258;                              // CLK/8, reset at the target, IRQ at the target, repeat
    TIMER_RELOAD(2) = (u16)((F_CPU / 8) / TICK_HZ);
    InterruptCallback(IRQ_TIMER2, &seq_tick);
    ExitCriticalSection();
}
